<?php $status=['draft'=>'مسودة','approved'=>'معتمد','cancelled'=>'ملغي'];$approved=$entry['status']==='approved';$section=$approved?$entry['work_section_code_snapshot'].' - '.$entry['work_section_name_snapshot']:$entry['current_section_code'].' - '.$entry['current_section_name'];$code=$approved?$entry['cost_code_snapshot'].' - '.$entry['cost_code_name_snapshot']:$entry['current_cost_code'].' - '.$entry['current_cost_code_name'];?>
<div class="page-header mb-4"><div class="row align-items-center"><div class="col"><div class="page-pretitle"><?=e($entry['cost_entry_code'])?></div><h2 class="page-title">تفاصيل قيد التكلفة</h2></div><?php if($entry['status']==='draft'&&$canEdit):?><div class="col-auto"><a class="btn btn-primary" href="/project-costs/<?=$entry['id']?>/edit">تعديل</a></div><?php endif;?></div></div><div class="card"><div class="card-body"><dl class="row"><?php foreach(['cost_date'=>'التاريخ','project_name'=>'المشروع','vendor_name'=>'المورد','description'=>'الوصف','reference_number'=>'المرجع','amount'=>'المبلغ','source_type'=>'المصدر','created_by_name'=>'أنشأ بواسطة','approved_by_name'=>'اعتمد بواسطة']as$k=>$l):?><dt class="col-sm-3 mb-2"><?=$l?></dt><dd class="col-sm-9 mb-2"><?=e($entry[$k]?:'—')?></dd><?php endforeach;?><dt class="col-sm-3 mb-2">قسم الأعمال</dt><dd class="col-sm-9 mb-2"><?=e($section)?></dd><dt class="col-sm-3 mb-2">كود التكلفة</dt><dd class="col-sm-9 mb-2"><?=e($code)?></dd><dt class="col-sm-3">الحالة</dt><dd class="col-sm-9"><?=e($status[$entry['status']]??$entry['status'])?></dd></dl></div><?php if($entry['status']==='draft'):?><div class="card-footer d-flex gap-2"><?php if($canApprove):?><form class="js-confirm-form" data-confirm="سيصبح القيد مالياً غير قابل للتعديل." method="post" action="/project-costs/<?=$entry['id']?>/approve"><input type="hidden" name="_token" value="<?=e($csrfToken)?>"><button class="btn btn-success">اعتماد</button></form><?php endif;?><?php if($canCancel):?><form class="js-confirm-form" data-confirm="سيتم إلغاء المسودة نهائياً." method="post" action="/project-costs/<?=$entry['id']?>/cancel"><input type="hidden" name="_token" value="<?=e($csrfToken)?>"><button class="btn btn-outline-danger">إلغاء المسودة</button></form><?php endif;?></div><?php endif;?></div>
